const t=document.querySelector('.menu-toggle'),n=document.getElementById('navigation');
if(t){t.addEventListener('click',()=>{const o=n.classList.toggle('open');t.setAttribute('aria-expanded',o)});n.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{n.classList.remove('open');t.setAttribute('aria-expanded',false)}))}
const P={GBP:{o:'£99',s:'£149',w:'£499',b:'£299'},USD:{o:'$129',s:'$249',w:'$599',b:'$349'},EUR:{o:'€119',s:'€179',w:'€549',b:'€349'},AUD:{o:'A$179',s:'A$279',w:'A$899',b:'A$549'},CAD:{o:'CA$169',s:'CA$269',w:'CA$799',b:'CA$449'},NZD:{o:'NZ$189',s:'NZ$299',w:'NZ$999',b:'NZ$599'}};
function setC(c){document.querySelectorAll('[data-price]').forEach(e=>e.textContent=P[c][e.dataset.price]);document.querySelectorAll('.currency button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.c===c));try{localStorage.setItem('r2r-cur',c)}catch(e){}}
document.querySelectorAll('.currency button').forEach(b=>b.addEventListener('click',()=>setC(b.dataset.c)));
let s;try{s=localStorage.getItem('r2r-cur')}catch(e){}if(s&&P[s])setC(s);
document.getElementById('y')&&(document.getElementById('y').textContent=new Date().getFullYear());
const ob=document.getElementById('offerbar');try{if(localStorage.getItem('r2r-offer-x'))ob.remove()}catch(e){}
document.getElementById('offerclose')?.addEventListener('click',()=>{ob.remove();try{localStorage.setItem('r2r-offer-x','1')}catch(e){}});
const cb=document.getElementById('cookie-banner');function showCB(){cb&&(cb.style.display='block')}function hideCB(){cb&&(cb.style.display='none')}function acceptC(){try{localStorage.setItem('r2r-cookie','accept');if(typeof gtag==='function'){gtag('consent','update',{analytics_storage:'granted'})}if(typeof fbq==='function'){const s=document.createElement('script');s.async=true;s.src='https://connect.facebook.net/en_US/fbevents.js';s.onload=()=>{fbq('init','2172154956705270');fbq('track','PageView')};document.head.appendChild(s)}}catch(e){}hideCB()}function declineC(){try{localStorage.setItem('r2r-cookie','decline')}catch(e){}hideCB()}let cc;try{cc=localStorage.getItem('r2r-cookie')}catch(e){}if(!cc){showCB()}else if(cc==='accept'){if(typeof gtag==='function'){gtag('consent','update',{analytics_storage:'granted'})}if(typeof fbq==='function'){const s=document.createElement('script');s.async=true;s.src='https://connect.facebook.net/en_US/fbevents.js';s.onload=()=>{fbq('init','2172154956705270');fbq('track','PageView')};document.head.appendChild(s)}}document.getElementById('cookie-accept')?.addEventListener('click',acceptC);document.getElementById('cookie-decline')?.addEventListener('click',declineC);document.getElementById('cookie-settings-link')?.addEventListener('click',()=>{try{localStorage.removeItem('r2r-cookie')}catch(e){}showCB()});
const pf=document.querySelector('form[name="profile-check"]');if(pf){pf.addEventListener('submit',()=>{const eid=Date.now()+'_'+Math.random().toString(36).substr(2,9);try{localStorage.setItem('r2r-lead-eid',eid)}catch(e){}if(typeof gtag==='function'){gtag('event','generate_lead',{event_category:'engagement',event_label:'profile_check_form'})}if(typeof fbq==='function'&&localStorage.getItem('r2r-cookie')==='accept'){fbq('track','Lead',{},{eventID:eid})}})}
